import{_ as t}from"./chunks/high-level-architecture.DHexjYNQ.js";import{_ as a}from"./chunks/deployment-architecture.CnmbDTZS.js";import{_ as r,o as s,c as i,a2 as o}from"./chunks/framework.Ce1WstT_.js";const c="/fundsroom_infotech/assets/architecture/backend-layered-architecture.svg",b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/architecture.md","filePath":"system-design/architecture.md"}'),h={name:"system-design/architecture.md"};function n(l,e,d,u,p,m){return s(),i("div",null,[...e[0]||(e[0]=[o('<div class="page-header"><span class="category-badge">SYSTEM DESIGN</span><h1>Architecture</h1><p class="page-subtitle">Understand how the Fundsroom platform connects the frontend, backend, database, authentication, and business workflows.</p><hr class="header-divider"></div><p>The application follows a monolithic backend architecture with a separately deployed frontend and backend.</p><h2 id="high-level-architecture" tabindex="-1">High-Level Architecture <a class="header-anchor" href="#high-level-architecture" aria-label="Permalink to &quot;High-Level Architecture&quot;">​</a></h2><div class="architecture-container"><img src="'+t+'" alt="High-Level System Architecture"></div><p class="screenshot-caption">Figure 1 — High-Level System Architecture</p><h3 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h3><p>The system communicates unidirectionally via HTTP and TCP protocols. The React SPA interacts exclusively with the Express REST API via HTTPS, and the Express API communicates with the PostgreSQL database via TCP port 6543 (Supabase connection pool).</p><h2 id="target-deployment-architecture" tabindex="-1">Target Deployment Architecture <a class="header-anchor" href="#target-deployment-architecture" aria-label="Permalink to &quot;Target Deployment Architecture&quot;">​</a></h2><div class="architecture-container"><img src="'+a+'" alt="Target Deployment Architecture"></div><p class="screenshot-caption">Figure 2 — Target Deployment Architecture</p><h3 id="how-it-works-1" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works-1" aria-label="Permalink to &quot;How it works&quot;">​</a></h3><p>Vercel hosts the React frontend, Railway hosts the Node.js Express backend API, Supabase hosts the PostgreSQL database, and GitHub Pages hosts this documentation. This forms our production deployment topology.</p><h2 id="backend-layered-architecture" tabindex="-1">Backend Layered Architecture <a class="header-anchor" href="#backend-layered-architecture" aria-label="Permalink to &quot;Backend Layered Architecture&quot;">​</a></h2><div class="architecture-container"><img src="'+c+'" alt="Backend Layered Architecture"></div><p class="screenshot-caption">Figure 3 — Backend Layered Architecture</p><h3 id="how-it-works-2" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works-2" aria-label="Permalink to &quot;How it works&quot;">​</a></h3><p>The Node.js Express backend strictly isolates responsibilities passing from the HTTP layer down to the database level, following Clean Architecture principles. Incoming requests pass through middleware (auth, RBAC, zod) to controllers, which hand off business workflows to services, which utilize repositories for database access.</p>',17)])])}const f=r(h,[["render",n]]);export{b as __pageData,f as default};
